query Order($number: String!) {
  order(number: $number) {
    number
    step
    placedAt
    customerName
    purchaseOrderNumber
    currency
    lines {
      lineNo
      sku
      productName
      unitName
      quantity
      unitPrice {
        amount
        currency
      }
      net {
        amount
        currency
      }
    }
    taxes {
      lineNo
      name
      rate
      amount {
        amount
        currency
      }
    }
    shippingMethod
    subtotal {
      amount
      currency
    }
    discount {
      amount
      currency
    }
    shipping {
      amount
      currency
    }
    shippingDiscount {
      amount
      currency
    }
    tax {
      amount
      currency
    }
    grandTotal {
      amount
      currency
    }
    paymentMethod
    paymentTermDays
    dueOn
    sellerTaxId
    taxExemptionCertificate
    billingAddress {
      label
      countryCode
      line1
      line2
      city
      regionCode
      postalCode
      gstin
    }
    shippingAddress {
      label
      countryCode
      line1
      line2
      city
      regionCode
      postalCode
      gstin
    }
  }
}

d97d2b7450e3ea57de5457fc9439ddd90693198d:
query Orders($first: Int, $after: String) {
  orders(first: $first, after: $after) {
    nodes {
      number
      step
      placedAt
      customerName
      purchaseOrderNumber
      grandTotal {
        amount
        currency
      }
    }
    nextAfter
  }
}

ee664f4f6929e222d63ac7fae62e351b0f2f9c3c:
query Product($sku: String!) {
  product(sku: $sku) {
    id
    sku
    name
    category {
      id
      name
      parentId
    }
    attributes {
      key
      values
    }
    primaryUnit {
      code
      name
      precision
    }
    units {
      code
      name
      precision
    }
    price {
      unitPrice {
        amount
        currency
      }
      unitCode
      quantity
      minQuantity
    }
  }
}

1f638264b5b6c9b2579142c8e5242adf3697b6c5:
query ProductPrice($sku: String!, $unitCode: String!, $quantity: String!) {
  product(sku: $sku) {
    id
    price(unitCode: $unitCode, quantity: $quantity) {
      unitPrice {
        amount
        currency
      }
      unitCode
      quantity
      minQuantity
    }
  }
}

