query Products($categoryId: ID, $includeSubcategories: Boolean, $first: Int, $after: String) {
  products(
    categoryId: $categoryId
    includeSubcategories: $includeSubcategories
    first: $first
    after: $after
  ) {
    nodes {
      id
      sku
      name
      category {
        id
        name
      }
      primaryUnit {
        code
        name
        precision
      }
      price {
        unitPrice {
          amount
          currency
        }
        unitCode
      }
    }
    nextAfter
  }
}

d77bdbd9b2b7b0c4a7b2624b2cee9640bc91e3d5:
query Search($query: String!, $first: Int, $offset: Int) {
  search(query: $query, first: $first, offset: $offset) {
    nodes {
      match
      product {
        id
        sku
        name
        category {
          id
          name
        }
        primaryUnit {
          code
          name
          precision
        }
        price {
          unitPrice {
            amount
            currency
          }
          unitCode
        }
      }
    }
    nextOffset
  }
}

